import React from 'react';
import {View, Text, StyleSheet, TouchableOpacity, Alert} from 'react-native';

//First navigate to GrusGorls folder in terminal using cd then navigate to Product folder using cd Product
//To run server use npm start in terminal
//To see what it looks like in app form, right click inspect and click on the app tab
// ctrl + c to stop server

class HelloThere extends React.Component {
  clickMe() {
    Alert.alert("Hi!")
  }
  render() {
    return (
      <TouchableOpacity onPress={this.clickMe()}>
        <View style={styles.box}>
          <Text>Hello {this.props.name}. Please click me.</Text>
        </View>
      </TouchableOpacity>
    );
  }
}

var styles = StyleSheet.create({
  box: {
    borderColor: 'red',
    backgroundColor: '#fff',
    borderWidth: 1,
    padding: 10,
    width: 100,
    height: 100
  }
});

React.render(<HelloThere name="Component" />, document.getElementById('content'));

